// New keys use English until dedicated locale translations are supplied.
const FALLBACK_TRANSLATIONS = PHRASES.slice(374);

function dictionary(translations: readonly string[]): Dict {
  return Object.fromEntries(PHRASES.map((phrase, index) => [phrase, translations[index]]));
}

